/*
 * config.h - build settings for Imperium on Linux.
 *
 * This used to be generated by autoconf's configure script. Imperium now
 * only targets Linux, where all of these are always true, so the file is
 * simply kept in the source tree.
 *
 * This program is free software; you can redistribute it and/or modify
 * it under the terms of the GNU General Public License as published by
 * the Free Software Foundation; either version 1, or (at your option)
 * any later version.
 */

#ifndef IMP_CONFIG_H
#define IMP_CONFIG_H

/* System headers and functions every Linux system has */
#define HAVE_STDLIB_H 1
#define HAVE_STRING_H 1
#define HAVE_STRINGS_H 1
#define HAVE_STDARG_H 1
#define HAVE_UNISTD_H 1
#define HAVE_TERMIOS_H 1
#define HAVE_SELECT 1

/* Use crypt() (from libcrypt) to protect the client/server codes */
#define HAVE_CRYPT 1

/* Open FIFOs read/write so a reader never sees end-of-file just because
   no writer currently has the pipe open */
#define BROKEN_PIPE 1

/* mknod()/mkfifo() modes are limited by the umask, so chmod() afterwards */
#define BROKEN_MKNOD 1

#endif /* IMP_CONFIG_H */
